import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // The fuzzed parameter is the amount of wei sent to go. We let the fuzzer choose caller too via address.
    function testFuzz_property(uint256 amount, address caller) public {
        // keep amount in a reasonable wide domain but avoid overflow issues
        amount = bound(amount, 0, 1e20);
        // avoid the zero address as caller for vm.prank
        vm.assume(caller != address(0));

